import torch
def apply_interleaved_rope(x, mrope_section):
    x_t = x[0].clone()
    x_t[..., 1:mrope_section[1] * 3:3] = x[1, ..., 1:mrope_section[1] * 3:3]
    x_t[..., 2:mrope_section[2] * 3:3] = x[2, ..., 2:mrope_section[2] * 3:3]
    return x_t

def non_interleaved(cos, mrope_section):
    return torch.cat([
        m[i] for i, m in enumerate(
            cos.split(mrope_section, dim=-1))
    ], dim=-1)

def transform(cos, mrope_section, interleaved):
    if interleaved:
        return apply_interleaved_rope(cos, mrope_section)
    else:
        return non_interleaved(cos, mrope_section)

# Let's test with small dimensions
t, h, w = 5, 3, 2
half = t + h + w
# create cos with distinct values per modality per frequency index
cos = torch.zeros(3, 1, half)
for mod in range(3):
    start = sum([t,h,w][:mod])
    end = start + [t,h,w][mod]
    for idx in range(start, end):
        cos[mod, 0, idx] = mod * 1000 + idx

print("Chunked cos:")
for mod in range(3):
    print(f"  mod {mod}:", cos[mod, 0])
print("Non-interleaved result:")
ni = transform(cos, [t,h,w], False)
print("  ", ni[0])
print("Interleaved result:")
il = transform(cos, [t,h,w], True)
print("  ", il[0])
# compute mapping
mapping_ni = {}
for f in range(half):
    val = ni[0, f].item()
    # find source modality
    for mod in range(3):
        if torch.isclose(cos[mod, 0, f], torch.tensor(val)):
            mapping_ni[f] = mod
            break
print("Non-interleaved mapping:", mapping_ni)
mapping_il = {}
for f in range(half):
    val = il[0, f].item()
    if val == 0:
        continue
    found = False
    for mod in range(3):
        idx = torch.where(cos[mod,0] == val)
        if len(idx[0]) > 0:
            mapping_il[f] = mod
            found = True
            break
    if not found:
        print(f"Value {val} not found")
print("Interleaved mapping:", mapping_il)
# invert
inv = {0:[],1:[],2:[]}
for idx, mod in mapping_il.items():
    inv[mod].append(idx)
print("Modality->indices:", inv)
# Let's also compute expected interleaving by simulating round-robin
# We'll generate sequence by iterating i from 0 and picking T, H, W while available
seq = []
remaining = [t, h, w]
i = 0
while any(r > 0 for r in remaining):
    for mod in range(3):
        if remaining[mod] > 0:
            seq.append(mod)
            remaining[mod] -= 1
print("Round-robin sequence:", seq)
# compare with mapping indices order
ordered = [mapping_il.get(i, -1) for i in range(half) if i in mapping_il]
print("Mapping order:", ordered)
