import torch
def compute_masks(t, h, w):
    half = t + h + w
    t_mask = torch.zeros(half, dtype=torch.bool)
    h_mask = torch.zeros(half, dtype=torch.bool)
    w_mask = torch.zeros(half, dtype=torch.bool)
    remaining = [t, h, w]
    f = 0
    while f < half:
        for mod in range(3):
            if remaining[mod] > 0:
                if mod == 0:
                    t_mask[f] = True
                elif mod == 1:
                    h_mask[f] = True
                else:
                    w_mask[f] = True
                remaining[mod] -= 1
                f += 1
                if f == half:
                    break
        # after each full round, continue
    return t_mask, h_mask, w_mask

def simple_modulo_masks(t, h, w):
    half = t + h + w
    t_mask = torch.zeros(half, dtype=torch.bool)
    h_mask = torch.zeros(half, dtype=torch.bool)
    w_mask = torch.zeros(half, dtype=torch.bool)
    for f in range(half):
        offset = f % 3
        group = f // 3
        if offset == 0 and group < t:
            t_mask[f] = True
        elif offset == 1 and group < h:
            h_mask[f] = True
        elif offset == 2 and group < w:
            w_mask[f] = True
        else:
            # need to assign to some modality (maybe shift)
            pass
    return t_mask, h_mask, w_mask

