import torch
import numpy as np

def apply_interleaved_rope(x, mrope_section):
    x_t = x[0].clone()
    x_t[..., 1:mrope_section[1] * 3:3] = x[1, ..., 1:mrope_section[1] * 3:3]
    x_t[..., 2:mrope_section[2] * 3:3] = x[2, ..., 2:mrope_section[2] * 3:3]
    return x_t

def compute_masks_interleaved(t, h, w, half):
    # emulate triton vectorized masks
    t_mask = np.zeros(half, dtype=bool)
    h_mask = np.zeros(half, dtype=bool)
    w_mask = np.zeros(half, dtype=bool)
    for idx in range(half):
        offset = idx % 3
        group = idx // 3
        if offset == 1 and group < h:
            h_mask[idx] = True
        elif offset == 2 and group < w:
            w_mask[idx] = True
        else:
            t_mask[idx] = True
    return t_mask, h_mask, w_mask

def compute_masks_chunked(t, h, w, half):
    t_mask = np.zeros(half, dtype=bool)
    h_mask = np.zeros(half, dtype=bool)
    w_mask = np.zeros(half, dtype=bool)
    for idx in range(half):
        if idx < t:
            t_mask[idx] = True
        elif idx < t + h:
            h_mask[idx] = True
        else:
            w_mask[idx] = True
    return t_mask, h_mask, w_mask

def test_random():
    import random
    for _ in range(20):
        t = random.randint(1, 10)
        h = random.randint(1, 10)
        w = random.randint(1, 10)
        half = t + h + w
        # interleaved mapping via function
        x = torch.randn(3, 1, half)
        for mod in range(3):
